"use strict";

let toastTimer = null;
let uiTooltipTimer = null;
let activeHintEl = null;
let lastAudioSaveAt = 0;
let autoPlayChainActive = false;
let isWindowFullscreen = false;

function qs(sel, root) {
  return (root || document).querySelector(sel);
}

function qsa(sel, root) {
  return Array.from((root || document).querySelectorAll(sel));
}

function getOrCreateUITooltip() {
  return qs("#ui-tooltip");
}

function hideUITooltip() {
  if (uiTooltipTimer) {
    clearTimeout(uiTooltipTimer);
    uiTooltipTimer = null;
  }
  activeHintEl = null;
  const tip = qs("#ui-tooltip");
  if (tip) {
    tip.classList.add("hidden");
  }
}

function positionAndShowUITooltip(anchorEl) {
  if (!anchorEl || !anchorEl.isConnected) {
    hideUITooltip();
    return;
  }
  const parentSelect = anchorEl.closest(".custom-select");
  if (parentSelect && parentSelect.classList.contains("open")) {
    hideUITooltip();
    return;
  }
  const text = (anchorEl.getAttribute("data-hint") || "").trim();
  if (!text) {
    hideUITooltip();
    return;
  }
  const tip = getOrCreateUITooltip();
  if (!tip) return;
  tip.textContent = text;
  tip.classList.remove("hidden");

  const rect = anchorEl.getBoundingClientRect();
  const tipW = tip.offsetWidth || 120;
  const tipH = tip.offsetHeight || 26;
  const vw = window.innerWidth || 800;
  const vh = window.innerHeight || 600;

  let left = rect.left + rect.width / 2 - tipW / 2;
  left = Math.max(8, Math.min(vw - tipW - 8, left));

  let top = rect.bottom + 6;
  if (top + tipH > vh - 8 && rect.top - tipH - 6 >= 8) {
    top = rect.top - tipH - 6;
  } else {
    top = Math.max(8, Math.min(vh - tipH - 8, top));
  }

  tip.style.left = Math.round(left) + "px";
  tip.style.top = Math.round(top) + "px";
}

function setElementHint(el, text) {
  if (!el) return;
  el.removeAttribute("title");
  if (text) {
    el.setAttribute("data-hint", text);
  } else {
    el.removeAttribute("data-hint");
  }
  if (activeHintEl === el) {
    const tip = qs("#ui-tooltip");
    if (tip && !tip.classList.contains("hidden")) {
      positionAndShowUITooltip(el);
    }
  }
}

function syncFullscreenButtonState() {
  const enterIcon = qs("#icon-fullscreen-enter");
  const exitIcon = qs("#icon-fullscreen-exit");
  const btn = qs("#btn-toggle-fullscreen");
  if (enterIcon) enterIcon.classList.toggle("hidden", isWindowFullscreen);
  if (exitIcon) exitIcon.classList.toggle("hidden", !isWindowFullscreen);
  if (btn) {
    setElementHint(
      btn,
      isWindowFullscreen ? "Wróć do trybu okienkowego" : "Przełącz pełny ekran"
    );
  }
}

function setFullscreenUIState(active) {
  isWindowFullscreen = Boolean(active);
  syncFullscreenButtonState();
}

document.addEventListener("fullscreenchange", () => {
  setFullscreenUIState(Boolean(document.fullscreenElement || document.webkitFullscreenElement));
});

document.addEventListener("webkitfullscreenchange", () => {
  setFullscreenUIState(Boolean(document.fullscreenElement || document.webkitFullscreenElement));
});

function showToast(message) {
  const banner = qs("#toast-banner");
  if (!banner || !message) return;
  banner.textContent = message;
  banner.classList.remove("hidden");
  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    banner.classList.add("hidden");
  }, 2800);
}

function syncTopbarToggleIcons() {
  const isLarge = document.body.getAttribute("data-ui-scale") === "large";
  const zoomInIcon = qs("#icon-zoom-in");
  const zoomOutIcon = qs("#icon-zoom-out");
  const zoomBtn = qs("#btn-toggle-ui-scale");
  if (zoomInIcon) zoomInIcon.classList.toggle("hidden", isLarge);
  if (zoomOutIcon) zoomOutIcon.classList.toggle("hidden", !isLarge);
  if (zoomBtn) {
    setElementHint(
      zoomBtn,
      isLarge ? "Pomniejsz przyciski i kontrolki (- / Ctrl+-)" : "Powiększ przyciski i kontrolki (+ / Ctrl++)"
    );
  }

  const isImagelessLocked = document.body.getAttribute("data-imageless-locked") === "true";
  const isImageless = isImagelessLocked || document.body.getAttribute("data-imageless") === "true";
  const imgIconOn = qs("#icon-imageless-off");
  const imgIconOff = qs("#icon-imageless-on");
  const imgBtn = qs("#btn-toggle-imageless");
  if (imgIconOn) imgIconOn.classList.toggle("hidden", isImageless);
  if (imgIconOff) imgIconOff.classList.toggle("hidden", !isImageless);
  if (imgBtn) {
    imgBtn.disabled = isImagelessLocked;
    imgBtn.classList.toggle("is-disabled", isImagelessLocked);
    imgBtn.classList.toggle("active", isImageless);
    setElementHint(
      imgBtn,
      isImagelessLocked
        ? "Obrazy wyłączone w ustawieniach książki (imageless: true)"
        : isImageless
          ? "Włącz obrazy (tryb bez obrazów aktywny)"
          : "Wyłącz obrazy (tryb tekstowy na środku)"
    );
  }

  const isLightTheme = document.body.getAttribute("data-theme") === "light";
  const sunIcon = qs("#icon-theme-sun");
  const moonIcon = qs("#icon-theme-moon");
  if (sunIcon) sunIcon.classList.toggle("hidden", isLightTheme);
  if (moonIcon) moonIcon.classList.toggle("hidden", !isLightTheme);
}

function toggleUIScaleClient(forcedScale) {
  const currentScale = document.body.getAttribute("data-ui-scale") === "large" ? "large" : "small";
  const nextScale =
    forcedScale === "large" || forcedScale === "small"
      ? forcedScale
      : currentScale === "large"
        ? "small"
        : "large";
  document.body.setAttribute("data-ui-scale", nextScale);
  syncTopbarToggleIcons();
  if (typeof initSceneTextModalFeed === "function") {
    initSceneTextModalFeed(false);
  }
  sendServerAction("ToggleUIScale", { scale: nextScale });
}

function decodeHeaderUTF8(raw) {
  if (!raw) return "";
  let allLatin1 = true;
  let hasHighByte = false;
  for (let i = 0; i < raw.length; i++) {
    const code = raw.charCodeAt(i);
    if (code > 0xff) {
      allLatin1 = false;
      break;
    }
    if (code >= 0x80) {
      hasHighByte = true;
    }
  }
  if (allLatin1 && hasHighByte && typeof TextDecoder !== "undefined") {
    try {
      const bytes = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i++) {
        bytes[i] = raw.charCodeAt(i) & 0xff;
      }
      return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    } catch (_) {}
  }
  return raw;
}

function syncEditorHistoryHeaders(resp) {
  if (!resp || !resp.headers) return;
  const canUndoHeader = resp.headers.get("X-Can-Undo");
  const canRedoHeader = resp.headers.get("X-Can-Redo");
  const histCountHeader = resp.headers.get("X-History-Count");
  const undoTitleHeader = decodeHeaderUTF8(resp.headers.get("X-Undo-Title"));
  const redoTitleHeader = decodeHeaderUTF8(resp.headers.get("X-Redo-Title"));

  if (canUndoHeader !== null) {
    const canUndo = canUndoHeader === "true";
    const undoBtn = qs("#btn-editor-undo");
    if (undoBtn) {
      undoBtn.disabled = !canUndo;
      undoBtn.classList.toggle("is-disabled", !canUndo);
      if (undoTitleHeader) {
        setElementHint(undoBtn, undoTitleHeader);
      }
    }
  }

  if (canRedoHeader !== null) {
    const canRedo = canRedoHeader === "true";
    const redoBtn = qs("#btn-editor-redo");
    if (redoBtn) {
      redoBtn.disabled = !canRedo;
      redoBtn.classList.toggle("is-disabled", !canRedo);
      if (redoTitleHeader) {
        setElementHint(redoBtn, redoTitleHeader);
      }
    }
  }

  if (histCountHeader !== null) {
    const count = parseInt(histCountHeader, 10) || 0;
    const badge = qs("#history-unsaved-badge");
    if (badge) {
      badge.textContent = String(count);
      badge.classList.toggle("hidden", count <= 0);
    }
  }

  const histPreviewHeader = resp.headers.get("X-History-Preview");
  if (histPreviewHeader === "true" || histPreviewHeader === "false") {
    document.body.setAttribute("data-history-preview", histPreviewHeader);
    const edView = qs("#view-editor");
    if (edView) {
      edView.setAttribute("data-history-preview", histPreviewHeader);
      edView.classList.toggle("is-history-preview", histPreviewHeader === "true");
    }
  }
}

function applyServerResponseHeaders(resp, actionName) {
  syncEditorHistoryHeaders(resp);
  const theme = resp.headers.get("X-Theme");
  if (theme) {
    document.body.setAttribute("data-theme", theme);
    if (typeof invalidateStudioThemeCache === "function") {
      invalidateStudioThemeCache();
    }
    if (typeof renderStudioCanvas === "function") {
      renderStudioCanvas();
    }
  }

  const imagelessLocked = resp.headers.get("X-Imageless-Locked");
  if (imagelessLocked) {
    document.body.setAttribute("data-imageless-locked", imagelessLocked);
  }

  const imageless = resp.headers.get("X-Imageless");
  if (imageless) {
    const effectiveImageless = imageless === "true" || document.body.getAttribute("data-imageless-locked") === "true";
    document.body.setAttribute("data-imageless", effectiveImageless ? "true" : "false");
    const playerLayout = qs("#player-layout");
    if (playerLayout) {
      playerLayout.classList.toggle("is-imageless", effectiveImageless);
    }
    const sceneTextLayout = qs(".scene-text-book-layout");
    if (sceneTextLayout) {
      const hasSceneImg = Boolean(qs(".player-bg-img", sceneTextLayout));
      sceneTextLayout.classList.toggle("is-imageless", effectiveImageless || !hasSceneImg);
    }
  }

  const uiScale = resp.headers.get("X-UI-Scale");
  if (uiScale) {
    document.body.setAttribute("data-ui-scale", uiScale);
  }

  const audioSpeed = resp.headers.get("X-Audio-Speed");
  if (audioSpeed) {
    const audioEl = qs("#story-audio");
    const speedNum = parseFloat(audioSpeed) || 1.0;
    if (audioEl) {
      audioEl.setAttribute("data-speed", audioSpeed);
      audioEl.playbackRate = speedNum;
    }
    const speedBtn = qs("#btn-audio-speed");
    if (speedBtn) {
      speedBtn.textContent = audioSpeed + "x";
    }
  }

  const autoChoice = resp.headers.get("X-Auto-Choice");
  if (autoChoice) {
    const isAutoOn = autoChoice === "true";
    const audioEl = qs("#story-audio");
    if (audioEl) {
      audioEl.setAttribute("data-auto-choice", autoChoice);
    }
    const autoBtn = qs("#btn-auto-choice-toggle");
    if (autoBtn) {
      autoBtn.classList.toggle("chip-active", isAutoOn);
      setElementHint(autoBtn, isAutoOn ? "Auto-Wybór: WŁ" : "Auto-Wybór: WYŁ");
    }
    if (actionName === "ToggleAutoChoice") {
      if (isAutoOn) {
        autoPlayChainActive = true;
        if (audioEl && audioEl.paused && audioEl.getAttribute("data-audio-url")) {
          audioEl.play().catch(() => {});
        } else if (
          (!audioEl || !audioEl.getAttribute("data-audio-url")) &&
          qsa('#active-scene-stage .choice-btn[action="ChooseBranch"]').length > 0
        ) {
          if (typeof autoAdvanceFallbackTimer !== "undefined" && autoAdvanceFallbackTimer) {
            clearTimeout(autoAdvanceFallbackTimer);
          }
          autoAdvanceFallbackTimer = setTimeout(() => {
            sendServerAction("AudioEnded", {});
          }, 1500);
        }
      } else {
        autoPlayChainActive = false;
        if (typeof autoAdvanceFallbackTimer !== "undefined" && autoAdvanceFallbackTimer) {
          clearTimeout(autoAdvanceFallbackTimer);
          autoAdvanceFallbackTimer = null;
        }
      }
    }
  }

  
  const nativeCmd = resp.headers.get("X-Native-Cmd");
  if (nativeCmd === "toggle-fullscreen") {
    if (
      (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.storytellerHost) ||
      (window.chrome && window.chrome.webview) ||
      window.__storytellerNativeHost
    ) {
      isWindowFullscreen = !isWindowFullscreen;
    } else if (document.documentElement.requestFullscreen) {
      if (!document.fullscreenElement) {
        isWindowFullscreen = true;
        document.documentElement.requestFullscreen().catch(() => {});
      } else {
        isWindowFullscreen = false;
        document.exitFullscreen().catch(() => {});
      }
    } else {
      isWindowFullscreen = !isWindowFullscreen;
    }
  } else if (nativeCmd === "quit" || actionName === "QuitApp" || actionName === "PromptQuitApp") {
    if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.storytellerHost) {
      window.webkit.messageHandlers.storytellerHost.postMessage("quit");
    } else if (window.chrome && window.chrome.webview && typeof window.chrome.webview.postMessage === "function") {
      window.chrome.webview.postMessage("quit");
    }
    window.close();
    return true;
  }

  syncFullscreenButtonState();
  syncTopbarToggleIcons();

  const toast = decodeHeaderUTF8(resp.headers.get("X-Toast"));
  if (toast) {
    showToast(toast);
  }
  return false;
}

async function sendServerAction(actionName, params) {
  hideUITooltip();
  params = params || {};
  if (
    actionName === "UndoEditor" ||
    actionName === "ToggleEditorHistoryPanel" ||
    actionName === "OpenEditorHistoryPanel" ||
    actionName === "PreviewHistoryRevision" ||
    actionName === "PlayHistoryRevision" ||
    actionName === "SaveHistoryVersion" ||
    actionName === "CreateHistoryBranch" ||
    actionName === "SwitchHistoryBranch" ||
    actionName === "CopyHistoryRevisionToBranch" ||
    actionName === "CloseSceneTextModal" ||
    actionName === "NavigateSceneTextModal" ||
    actionName === "SwitchView" ||
    actionName === "OpenBook"
  ) {
    if (typeof consumeDirtyInspectorFormIntoParams === "function") {
      consumeDirtyInspectorFormIntoParams(params);
    }
  } else if (
    actionName === "RedoEditor" ||
    actionName === "RestoreHistoryRevision" ||
    actionName === "ExitHistoryPreview"
  ) {
    if (typeof cancelPendingInspectorTimers === "function") {
      cancelPendingInspectorTimers();
    }
  }
  if (actionName === "SelectStudioScene" && params.scene) {
    if (typeof editorSelectionCleared !== "undefined") {
      editorSelectionCleared = false;
    }
    if (typeof selectedNodeIds !== "undefined") {
      selectedNodeIds.clear();
      selectedNodeIds.add(String(params.scene));
    }
  } else if (
    actionName === "PreviewHistoryRevision" ||
    actionName === "ExitHistoryPreview" ||
    actionName === "PlayHistoryRevision" ||
    actionName === "RestoreHistoryRevision" ||
    actionName === "CopyHistoryRevisionToBranch" ||
    actionName === "SwitchHistoryBranch" ||
    actionName === "UndoEditor" ||
    actionName === "RedoEditor"
  ) {
    if (typeof editorSelectionCleared !== "undefined") {
      editorSelectionCleared = false;
    }
    if (typeof selectedNodeIds !== "undefined") {
      selectedNodeIds.clear();
    }
  }

  if (actionName !== "SaveAudioTime" && typeof cancelMediaPrefetchQueue === "function") {
    cancelMediaPrefetchQueue();
  }

  const prevAudio = qs("#story-audio");
  const prevWasPlaying = prevAudio ? !prevAudio.paused && !prevAudio.ended : false;
  const prevAudioTime = prevAudio ? prevAudio.currentTime || 0 : 0;
  const prevAudioUrl = prevAudio ? prevAudio.getAttribute("data-audio-url") || "" : "";

  const form = new URLSearchParams();
  form.set("action", actionName);
  if (prevAudio && prevAudioTime > 0 && actionName !== "SaveAudioTime") {
    form.set("audio_time", String(Math.floor(prevAudioTime * 10) / 10));
  }
  if (params) {
    Object.keys(params).forEach((k) => {
      if (params[k] !== undefined && params[k] !== null) {
        form.set(k, String(params[k]));
      }
    });
  }

  const resp = await fetch("/api/action", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8",
      "X-Requested-With": "StoryTeller"
    },
    body: form.toString()
  });

  if (applyServerResponseHeaders(resp, actionName)) {
    return;
  }

  const targetSelector = resp.headers.get("X-Target") || "#app";
  const keepScroll = resp.headers.get("X-Keep-Scroll") === "true";

  if (resp.status === 204 || targetSelector === "none") {
    if (keepScroll && typeof updateFocusedSceneByViewport === "function") {
      requestAnimationFrame(() => {
        if (typeof restorePlayerScrollPosition === "function") {
          restorePlayerScrollPosition();
        } else {
          updateFocusedSceneByViewport();
        }
        if (typeof initSceneTextModalFeed === "function") {
          initSceneTextModalFeed(false);
        }
      });
    }
    return;
  }

  const html = await resp.text();
  if (!html && targetSelector !== "#modals-root") {
    return;
  }

  if (targetSelector === "#modals-root") {
    const modalsRoot = qs("#modals-root");
    const prevModalFeed = qs(".scene-text-editor-feed", modalsRoot);
    const prevModalScrollTop = prevModalFeed ? prevModalFeed.scrollTop : 0;
    if (modalsRoot) {
      modalsRoot.innerHTML = html;
    }
    if ((actionName === "NavigateSceneTextModal" || actionName === "SaveSceneTextModal") && params && params.scene_id) {
      const nd =
        typeof studioGraphState !== "undefined" && studioGraphState.nodeById
          ? studioGraphState.nodeById.get(String(params.scene_id))
          : null;
      const contextForm = qs("#editor-context-form");
      const matchesContext = Boolean(contextForm && contextForm.getAttribute("data-context-scene-id") === String(params.scene_id));
      if (params.text !== undefined) {
        const cleaned = String(params.text).trim().replace(/\s+/g, " ");
        let summaryText = "Kliknij, aby wpisać treść sceny...";
        if (cleaned) {
          const m = cleaned.match(/^.*?[.!?…](?=\s|$)/);
          summaryText = m ? m[0] : cleaned;
        }
        if (matchesContext) {
          const previewBody = qs(".node-text-preview-body, .node-text-snippet", contextForm);
          if (previewBody) {
            previewBody.textContent = summaryText;
          }
        }
      }
      if (params.name !== undefined) {
        const trimmedName = String(params.name).trim();
        if (nd) {
          nd.name = trimmedName || String(params.scene_id);
        }
        if (matchesContext) {
          const nameInput = qs('input[name="name"]', contextForm);
          if (nameInput) {
            nameInput.value = trimmedName;
          }
        }
      }
      Object.keys(params).forEach((k) => {
        if (k.startsWith("choice_label_")) {
          const idx = k.slice("choice_label_".length);
          const lbl = String(params[k]).trim() || "Wybór " + (Number(idx) + 1);
          if (nd && nd.ports && nd.ports[Number(idx)]) {
            nd.ports[Number(idx)].label = lbl;
          }
          if (matchesContext) {
            const chInput = qs('input[name="' + CSS.escape(k) + '"]', contextForm);
            if (chInput) {
              chInput.value = lbl;
            }
          }
        }
      });
      if (nd && typeof renderStudioCanvas === "function") {
        studioGraphState.staticBatchDirty = true;
        renderStudioCanvas();
      }
    }
    if (actionName === "OpenSceneTextModal" || actionName === "NavigateSceneTextModal") {
      if (typeof initSceneTextModalFeed === "function") {
        initSceneTextModalFeed(true);
      }
      const modalTa = qs("#modal-scene-textarea");
      if (modalTa && actionName === "OpenSceneTextModal") {
        modalTa.focus({ preventScroll: true });
      }
    } else if (
      actionName === "SaveSceneTextModal" ||
      actionName === "ToggleSceneTextSettings" ||
      actionName === "SetStartScene" ||
      actionName === "BrowseAddBookMedia" ||
      actionName === "AddBookMediaFromDisk" ||
      actionName === "AddChoice" ||
      actionName === "PromptRemoveChoice" ||
      actionName === "RemoveChoice" ||
      actionName === "ConfirmModalClose" ||
      actionName === "ConfirmModalAccept" ||
      actionName === "BranchChoiceScene" ||
      actionName === "ConnectChoice"
    ) {
      const feed = qs(".scene-text-editor-feed", modalsRoot);
      if (feed) {
        feed.scrollTop = prevModalScrollTop;
      }
      if (typeof initSceneTextModalFeed === "function") {
        initSceneTextModalFeed(false);
      }
    } else if (actionName === "OpenNewBookModal") {
      const newBookInp = qs("#new-book-title", modalsRoot);
      if (newBookInp) {
        setTimeout(() => {
          newBookInp.focus();
        }, 0);
      }
    }
    return;
  }

  if (targetSelector === "#editor-context-panel") {
    const existingPanel = qs("#editor-context-panel");
    const editorBody = qs("#editor-workspace-body");
    if (existingPanel) {
      existingPanel.outerHTML = html;
    } else if (editorBody && html) {
      editorBody.insertAdjacentHTML("afterbegin", html);
    }
    if (actionName === "SaveSceneTextModal" || actionName === "CloseSceneTextModal") {
      const modalsRoot = qs("#modals-root");
      if (modalsRoot) {
        modalsRoot.innerHTML = "";
      }
      const updatedForm = qs("#editor-context-form");
      const selId = updatedForm ? updatedForm.getAttribute("data-context-scene-id") || "" : "";
      if (selId && typeof studioGraphState !== "undefined" && studioGraphState.nodeById) {
        const nd = studioGraphState.nodeById.get(selId);
        if (nd) {
          const nameInp = qs('input[name="name"]', updatedForm);
          if (nameInp) {
            nd.name = nameInp.value.trim() || selId;
          }
          qsa('input[name^="choice_label_"]', updatedForm).forEach((inp) => {
            const idx = inp.getAttribute("data-choice-idx");
            if (idx !== null && nd.ports && nd.ports[Number(idx)]) {
              nd.ports[Number(idx)].label = inp.value.trim() || "Wybór " + (Number(idx) + 1);
            }
          });
          studioGraphState.staticBatchDirty = true;
        }
      }
    }
    const updatedForm = qs("#editor-context-form");
    const isNodeFormVisible = Boolean(updatedForm && !updatedForm.classList.contains("hidden"));
    const selId = isNodeFormVisible ? updatedForm.getAttribute("data-context-scene-id") || "" : "";
    if (selId && typeof selectedNodeIds !== "undefined" && typeof syncNodeSelectionDOM === "function") {
      if (actionName === "SelectStudioScene") {
        if (typeof editorSelectionCleared !== "undefined") {
          editorSelectionCleared = false;
        }
        selectedNodeIds.clear();
        selectedNodeIds.add(selId);
      } else if ((typeof editorSelectionCleared === "undefined" || !editorSelectionCleared) && selectedNodeIds.size <= 1) {
        selectedNodeIds.clear();
        selectedNodeIds.add(selId);
      }
      syncNodeSelectionDOM();
      if (typeof renderStudioCanvas === "function") {
        renderStudioCanvas();
      }
    }
    return;
  }

  const prevFeed = qs("#story-scroll-feed");
  const prevScrollTop = prevFeed ? prevFeed.scrollTop : null;
  const prevEditorViewport = qs("#timeline-scroll-viewport");
  const prevEditorScrollTop = prevEditorViewport ? prevEditorViewport.scrollTop : null;
  const prevEditorScrollLeft = prevEditorViewport ? prevEditorViewport.scrollLeft : null;
  const prevHistScroll = qs("#history-graph-scroll");
  const prevHistScrollTop = prevHistScroll ? prevHistScroll.scrollTop : null;
  const resetCanvas = resp.headers.get("X-Reset-Canvas") === "true";
  const isAnimatedSceneTransition =
    actionName === "ChooseBranch" ||
    actionName === "AutoAdvanceImplicit" ||
    actionName === "AudioEnded";

  if (resetCanvas && typeof resetEditorCanvasViewState === "function") {
    resetEditorCanvasViewState();
  }

  const targetEl = qs(targetSelector) || qs("#app");
  if (targetEl) {
    targetEl.innerHTML = html;
    if (targetSelector === "#workspace") {
      const modalsRoot = qs("#modals-root");
      if (modalsRoot && modalsRoot.innerHTML !== "") {
        modalsRoot.innerHTML = "";
      }
    }
    syncFullscreenButtonState();
    syncTopbarToggleIcons();
    syncEditorHistoryHeaders(resp);
    const nextEditorViewport = qs("#timeline-scroll-viewport");
    if (nextEditorViewport && prevEditorScrollTop !== null) {
      nextEditorViewport.scrollTop = prevEditorScrollTop;
      nextEditorViewport.scrollLeft = prevEditorScrollLeft || 0;
    }
    const nextHistScroll = qs("#history-graph-scroll");
    if (nextHistScroll && prevHistScrollTop !== null && actionName !== "SaveHistoryVersion" && actionName !== "CreateHistoryBranch") {
      nextHistScroll.scrollTop = prevHistScrollTop;
    }
    if (typeof updateHistoryScrollCue === "function") {
      requestAnimationFrame(() => {
        updateHistoryScrollCue();
      });
    }

    const nextAudio = qs("#story-audio");
    const nextAutoChoice = nextAudio ? nextAudio.getAttribute("data-auto-choice") === "true" : false;
    const nextAudioUrl = nextAudio ? nextAudio.getAttribute("data-audio-url") || "" : "";

    let shouldAutoPlay = prevWasPlaying || actionName === "AudioEnded";
    if (actionName === "ToggleAutoChoice" && nextAutoChoice) {
      shouldAutoPlay = true;
      autoPlayChainActive = true;
    } else if (actionName === "ToggleAutoChoice" && !nextAutoChoice) {
      autoPlayChainActive = false;
    } else if (nextAutoChoice && (actionName === "ChooseBranch" || actionName === "AudioEnded" || autoPlayChainActive)) {
      shouldAutoPlay = true;
      autoPlayChainActive = true;
    }

    const preserveTime =
      keepScroll && prevAudioUrl && prevAudioUrl === nextAudioUrl ? prevAudioTime : null;

    initPlayerScrollAndAudio(
      keepScroll ? prevScrollTop : null,
      shouldAutoPlay,
      preserveTime,
      isAnimatedSceneTransition ? prevScrollTop : null
    );

    if (actionName === "OpenSceneTextModal") {
      if (typeof initSceneTextModalFeed === "function") {
        initSceneTextModalFeed(true);
      }
      const modalTa = qs("#modal-scene-textarea");
      if (modalTa) {
        modalTa.focus({ preventScroll: true });
      }
    }
  }
}

function postServerActionSilent(actionName, paramsOrFormData) {
  const body = new URLSearchParams();
  body.set("action", actionName);
  if (paramsOrFormData) {
    if (typeof FormData !== "undefined" && paramsOrFormData instanceof FormData) {
      paramsOrFormData.forEach((val, key) => {
        body.set(key, String(val));
      });
    } else {
      Object.keys(paramsOrFormData).forEach((k) => {
        if (paramsOrFormData[k] !== undefined && paramsOrFormData[k] !== null) {
          body.set(k, String(paramsOrFormData[k]));
        }
      });
    }
  }
  fetch("/api/action", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8",
      "X-Requested-With": "StoryTeller"
    },
    body: body.toString()
  })
    .then((resp) => {
      if (resp) {
        syncEditorHistoryHeaders(resp);
      }
    })
    .catch(() => {});
}

function bindDeclarativeActionBridge() {
  document.addEventListener("pointerover", (e) => {
    if (e.pointerType && e.pointerType !== "mouse" && e.pointerType !== "pen") {
      return;
    }
    const t = e.target;
    if (!t || !t.closest) return;
    const rawTitleEl = t.closest("[title]");
    if (rawTitleEl) {
      const rawVal = rawTitleEl.getAttribute("title") || "";
      rawTitleEl.removeAttribute("title");
      if (rawVal && !rawTitleEl.getAttribute("data-hint")) {
        rawTitleEl.setAttribute("data-hint", rawVal);
      }
    }
    const hintEl = t.closest("[data-hint]");
    if (hintEl === activeHintEl) return;
    if (uiTooltipTimer) {
      clearTimeout(uiTooltipTimer);
      uiTooltipTimer = null;
    }
    if (!hintEl || !(hintEl.getAttribute("data-hint") || "").trim()) {
      hideUITooltip();
      return;
    }
    activeHintEl = hintEl;
    const tip = qs("#ui-tooltip");
    if (tip && !tip.classList.contains("hidden")) {
      positionAndShowUITooltip(hintEl);
    } else {
      uiTooltipTimer = setTimeout(() => {
        uiTooltipTimer = null;
        if (activeHintEl === hintEl) {
          positionAndShowUITooltip(hintEl);
        }
      }, 120);
    }
  });

  document.addEventListener("pointerout", (e) => {
    if (!activeHintEl) return;
    const rel = e.relatedTarget;
    if (rel && activeHintEl.contains(rel)) {
      return;
    }
    const nextHint = rel && rel.closest ? rel.closest("[data-hint]") : null;
    if (!nextHint) {
      hideUITooltip();
    }
  });

  document.addEventListener("pointerdown", () => {
    hideUITooltip();
  });

  document.addEventListener("wheel", () => {
    hideUITooltip();
  }, { passive: true });

  document.addEventListener("scroll", () => {
    hideUITooltip();
  }, true);

  document.addEventListener("keydown", (e) => {
    hideUITooltip();
    const inEditableField = Boolean(
      e.target &&
        e.target.closest &&
        e.target.closest("input, textarea, select, [contenteditable]")
    );
    const hasZoomMod = Boolean(e.ctrlKey || e.metaKey);
    const isPlusKey =
      e.key === "+" ||
      e.key === "=" ||
      e.code === "Equal" ||
      e.code === "NumpadAdd";
    const isMinusKey =
      e.key === "-" ||
      e.key === "_" ||
      e.code === "Minus" ||
      e.code === "NumpadSubtract";
    const isZeroKey =
      e.key === "0" ||
      e.code === "Digit0" ||
      e.code === "Numpad0";

    if (!e.altKey) {
      if (
        (hasZoomMod && isPlusKey) ||
        (!hasZoomMod && !inEditableField && (e.key === "+" || e.key === "=" || e.code === "NumpadAdd"))
      ) {
        e.preventDefault();
        toggleUIScaleClient("large");
        return;
      }
      if (
        (hasZoomMod && isMinusKey) ||
        (!hasZoomMod && !inEditableField && (e.key === "-" || e.code === "NumpadSubtract"))
      ) {
        e.preventDefault();
        toggleUIScaleClient("small");
        return;
      }
      if (hasZoomMod && isZeroKey) {
        e.preventDefault();
        toggleUIScaleClient("small");
        return;
      }
    }

    if (e.key === "Escape") {
      const topbarMenu = qs("#topbar-actions-menu");
      const topbarToggle = qs("#btn-topbar-menu");
      if (topbarMenu) topbarMenu.classList.remove("open");
      if (topbarToggle) topbarToggle.classList.remove("active");
      if (typeof closeCanvasContextMenu === "function") {
        closeCanvasContextMenu();
      }
      if (typeof closeAllCustomSelects === "function") {
        closeAllCustomSelects(null);
      }
      const openBackdrop = qs("#modal-confirm[data-backdrop-action]") || qs(".modal-backdrop[data-backdrop-action]");
      if (openBackdrop) {
        const closeAct = openBackdrop.getAttribute("data-backdrop-action");
        if (closeAct) {
          sendServerAction(closeAct, {});
          return;
        }
      }
    }
  });

  document.addEventListener("mousedown", (e) => {
    if (e.button === 0) {
      let dragBarSelector = ".topbar";
            const dragBar = e.target.closest(dragBarSelector);
      if (dragBar && !e.target.closest("button, a, input, select, textarea, label, [action], .brand-logo")) {
        if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.storytellerHost) {
          window.webkit.messageHandlers.storytellerHost.postMessage("start-window-drag");
        } else {
          postServerActionSilent("StartWindowDrag");
        }
      }
    }
  });

  document.addEventListener("click", (e) => {
    const topbarMenuToggle = e.target.closest("[data-topbar-menu-toggle]");
    if (topbarMenuToggle) {
      e.preventDefault();
      e.stopPropagation();
      const menu = qs("#topbar-actions-menu");
      if (menu) {
        const willOpen = !menu.classList.contains("open");
        menu.classList.toggle("open", willOpen);
        topbarMenuToggle.classList.toggle("active", willOpen);
      }
      return;
    }
    if (!e.target.closest("#topbar-right")) {
      const menu = qs("#topbar-actions-menu");
      const toggleBtn = qs("#btn-topbar-menu");
      if (menu) menu.classList.remove("open");
      if (toggleBtn) toggleBtn.classList.remove("active");
    }

    if (typeof isEditorTouchClickSuppressed === "function" && isEditorTouchClickSuppressed(e)) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }

    if (e.target && e.target.classList && e.target.classList.contains("modal-backdrop")) {
      const backdropAction = e.target.getAttribute("data-backdrop-action");
      if (backdropAction) {
        sendServerAction(backdropAction, {});
        return;
      }
    }

    const settingsToggle = e.target.closest("[data-scene-settings-toggle]");
    if (settingsToggle) {
      e.preventDefault();
      e.stopPropagation();
      const settingsBlock = qs("#modal-scene-settings-block");
      const openInput = qs("#scene-settings-open-input");
      if (settingsBlock) {
        const willOpen = settingsBlock.classList.contains("hidden");
        settingsBlock.classList.toggle("hidden", !willOpen);
        settingsToggle.classList.toggle("active", willOpen);
        if (openInput) {
          openInput.value = willOpen ? "true" : "false";
        }
        if (typeof updateScrollMoreCue === "function") {
          updateScrollMoreCue(qs(".scene-text-editor-feed"), qs("#modal-scroll-more-cue"));
        }
      }
      return;
    }

    if (typeof handleEditorCanvasClick === "function" && handleEditorCanvasClick(e)) {
      return;
    }

    const submitBtn = e.target.closest('form[action] button[type="submit"], form[action] input[type="submit"]');
    if (submitBtn) {
      if (submitBtn.disabled || submitBtn.classList.contains("is-disabled")) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      const form = submitBtn.closest("form[action]");
      if (form) {
        e.preventDefault();
        e.stopPropagation();
        const actionName = (form.getAttribute("action") || "").trim();
        if (actionName) {
          const params = {};
          const fd = new FormData(form);
          fd.forEach((val, key) => {
            params[key] = val;
          });
          sendServerAction(actionName, params);
          return;
        }
      }
    }

    const target = e.target.closest("[action]");
    if (!target || target.tagName.toLowerCase() === "form" || target.disabled || target.classList.contains("is-disabled")) {
      return;
    }
    const actionName = (target.getAttribute("action") || "").trim();
    if (!actionName) {
      return;
    }
    if (actionName === "ToggleImageless" && document.body.getAttribute("data-imageless-locked") === "true") {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    e.preventDefault();
    e.stopPropagation();

    const params = {};
    const isModalOnlyAction =
      actionName === "OpenSceneTextModal" ||
      actionName === "SelectStudioScene" ||
      actionName === "PromptDeleteScene" ||
      actionName === "PromptDeleteScenes";
    if (
      actionName === "CreateSceneAt" ||
      actionName === "InsertScene" ||
      actionName === "InsertSceneBefore" ||
      actionName === "BranchChoiceScene" ||
      actionName === "CreateChapterGroup"
    ) {
      if (typeof editorSelectionCleared !== "undefined") {
        editorSelectionCleared = false;
      }
      if (typeof selectedNodeIds !== "undefined") {
        selectedNodeIds.clear();
      }
    }
    const parentCardForm = target.closest("form.editor-context-form, form.timeline-node-card, form#form-scene-text, form#form-new-book");
    if (parentCardForm && (!isModalOnlyAction || (typeof dirtyInspectorForms !== "undefined" && dirtyInspectorForms.has(parentCardForm)))) {
      if (typeof dirtyInspectorForms !== "undefined") {
        dirtyInspectorForms.delete(parentCardForm);
      }
      if (typeof liveSaveTimers !== "undefined" && liveSaveTimers.has(parentCardForm)) {
        clearTimeout(liveSaveTimers.get(parentCardForm));
        liveSaveTimers.delete(parentCardForm);
      }
      const fd = new FormData(parentCardForm);
      fd.forEach((val, key) => {
        params[key] = val;
      });
    } else if (!isModalOnlyAction && target.dataset && target.dataset.scene) {
      const contextForm = qs("#editor-context-form");
      if (contextForm && contextForm.getAttribute("data-context-scene-id") === target.dataset.scene) {
        const fd = new FormData(contextForm);
        fd.forEach((val, key) => {
          params[key] = val;
        });
      }
    }
    Object.keys(target.dataset).forEach((k) => {
      const snakeKey = k.replace(/[A-Z]/g, (m) => "_" + m.toLowerCase());
      params[snakeKey] = target.dataset[k];
    });
    if (actionName === "PromptDeleteScenes" && !params.scenes && typeof selectedNodeIds !== "undefined" && selectedNodeIds.size > 0) {
      params.scenes = Array.from(selectedNodeIds).join(",");
    }
    const topbarMenu = qs("#topbar-actions-menu");
    const topbarToggle = qs("#btn-topbar-menu");
    if (topbarMenu) topbarMenu.classList.remove("open");
    if (topbarToggle) topbarToggle.classList.remove("active");
    sendServerAction(actionName, params);
  });

  document.addEventListener("submit", (e) => {
    const form = e.target.closest("form[action]");
    if (!form) return;
    e.preventDefault();

    const actionName = (form.getAttribute("action") || "").trim();
    if (!actionName) return;
    const params = {};
    const fd = new FormData(form);
    fd.forEach((val, key) => {
      params[key] = val;
    });
    sendServerAction(actionName, params);
  });

  window.addEventListener("resize", () => {
    if (typeof restorePlayerScrollPosition === "function") {
      restorePlayerScrollPosition();
    }
    if (typeof initSceneTextModalFeed === "function") {
      initSceneTextModalFeed(false);
    }
    if (typeof updateChapterGroupFrames === "function") {
      updateChapterGroupFrames();
    }
    if (typeof drawStudioWires === "function") {
      drawStudioWires();
    }
  });

  if (typeof bindEditorCanvasEvents === "function") {
    bindEditorCanvasEvents();
  }

  syncTopbarToggleIcons();
  if (typeof initPlayerScrollAndAudio === "function") {
    initPlayerScrollAndAudio(null);
  }
}

document.addEventListener("DOMContentLoaded", bindDeclarativeActionBridge);

"use strict";

function formatSeconds(sec) {
  if (!Number.isFinite(sec) || sec < 0) return "0:00";
  const total = Math.floor(sec);
  const m = Math.floor(total / 60);
  const s = total % 60;
  return m + ":" + (s < 10 ? "0" + s : s);
}

function setPlayButtonVisual(isPlaying) {
  const playIcon = qs("#icon-audio-play");
  const pauseIcon = qs("#icon-audio-pause");
  if (playIcon) playIcon.classList.toggle("hidden", isPlaying);
  if (pauseIcon) pauseIcon.classList.toggle("hidden", !isPlaying);
}

let autoAdvanceFallbackTimer = null;
let activePrefetchController = null;
const prefetchedMediaCache = new Set();

function cancelMediaPrefetchQueue() {
  if (activePrefetchController) {
    activePrefetchController.abort();
    activePrefetchController = null;
  }
}

function waitForImageReady(imgEl, signal) {
  return new Promise((resolve) => {
    if (!imgEl || !imgEl.getAttribute("src") || imgEl.complete) {
      resolve();
      return;
    }
    const done = () => {
      imgEl.removeEventListener("load", done);
      imgEl.removeEventListener("error", done);
      resolve();
    };
    imgEl.addEventListener("load", done, { once: true });
    imgEl.addEventListener("error", done, { once: true });
    if (signal) {
      signal.addEventListener("abort", done, { once: true });
    }
  });
}

function waitForAudioReady(audioEl, signal) {
  return new Promise((resolve) => {
    if (!audioEl || !audioEl.getAttribute("data-audio-url") || audioEl.readyState >= 4) {
      resolve();
      return;
    }
    const done = () => {
      audioEl.removeEventListener("canplaythrough", done);
      audioEl.removeEventListener("error", done);
      resolve();
    };
    audioEl.addEventListener("canplaythrough", done, { once: true });
    audioEl.addEventListener("error", done, { once: true });
    if (signal) {
      signal.addEventListener("abort", done, { once: true });
    }
  });
}

async function scheduleCurrentSceneMediaPrefetch(audioEl) {
  cancelMediaPrefetchQueue();
  const stage = qs("#active-scene-stage");
  if (!stage || typeof AbortController === "undefined") return;

  const rawUrls = stage.getAttribute("data-prefetch-urls") || "";
  if (!rawUrls) return;

  const urls = rawUrls
    .split(";")
    .map((u) => u.trim())
    .filter(Boolean);
  if (urls.length === 0) return;

  const controller = new AbortController();
  activePrefetchController = controller;
  const signal = controller.signal;

  const bgImg = qs("#player-bg-img");
  const portraitImg = qs(".scene-portrait-img", stage);
  await Promise.all([
    waitForAudioReady(audioEl, signal),
    waitForImageReady(bgImg, signal),
    waitForImageReady(portraitImg, signal)
  ]);

  if (signal.aborted) return;

  for (let i = 0; i < urls.length; i++) {
    if (signal.aborted) return;
    const targetUrl = urls[i];
    if (!targetUrl || prefetchedMediaCache.has(targetUrl)) {
      continue;
    }
    try {
      const resp = await fetch(targetUrl, {
        method: "GET",
        credentials: "same-origin",
        signal: signal
      });
      if (resp && resp.ok) {
        await resp.arrayBuffer();
        prefetchedMediaCache.add(targetUrl);
      }
    } catch (_) {
      if (signal.aborted) return;
    }
  }
}

function initAudioController(shouldAutoPlay, preservedTime) {
  if (autoAdvanceFallbackTimer) {
    clearTimeout(autoAdvanceFallbackTimer);
    autoAdvanceFallbackTimer = null;
  }
  cancelMediaPrefetchQueue();

  const audio = qs("#story-audio");
  if (!audio) {
    scheduleCurrentSceneMediaPrefetch(null);
    return;
  }

  const url = audio.getAttribute("data-audio-url") || "";
  const resumeTime =
    preservedTime !== null && preservedTime !== undefined
      ? preservedTime
      : parseFloat(audio.getAttribute("data-resume-time") || "0") || 0;
  const speed = parseFloat(audio.getAttribute("data-speed") || "1") || 1.0;
  const autoChoiceOn = audio.getAttribute("data-auto-choice") === "true";
  const slider = qs("#audio-seek-slider");
  const playBtn = qs("#btn-audio-play");
  const hasNextChoices = qsa('#active-scene-stage .choice-btn[action="ChooseBranch"]').length > 0;

  const setBufferingState = (buffering) => {
    if (playBtn) {
      playBtn.classList.toggle("is-buffering", Boolean(buffering));
    }
  };

  if (url) {
    audio.preload = "auto";
    audio.src = url;
    audio.playbackRate = speed;
    if (audio.readyState < 4) {
      setBufferingState(true);
      const clearBuffering = () => setBufferingState(false);
      audio.addEventListener("canplaythrough", clearBuffering, { once: true });
      audio.addEventListener("playing", clearBuffering, { once: true });
      audio.addEventListener("error", clearBuffering, { once: true });
    }
    if (resumeTime > 0.2) {
      audio.addEventListener(
        "loadedmetadata",
        () => {
          if (resumeTime < (audio.duration || 0) - 0.2) {
            audio.currentTime = resumeTime;
          }
        },
        { once: true }
      );
    }
    audio.load();
    if (shouldAutoPlay) {
      let autoPlayStarted = false;
      const startPlay = () => {
        if (autoPlayStarted) return;
        autoPlayStarted = true;
        setBufferingState(false);
        audio.playbackRate = speed;
        audio.play().catch(() => {});
      };
      if (audio.readyState >= 4) {
        startPlay();
      } else {
        setBufferingState(true);
        audio.addEventListener("canplaythrough", startPlay, { once: true });
      }
    }
  } else if (shouldAutoPlay && autoChoiceOn && hasNextChoices) {
    autoAdvanceFallbackTimer = setTimeout(() => {
      sendServerAction("AudioEnded", {});
    }, 1500);
  }

  scheduleCurrentSceneMediaPrefetch(audio);

  if (playBtn) {
    playBtn.addEventListener("click", () => {
      if (!url) {
        showToast("Ta scena nie posiada przypisanego pliku audio.");
        return;
      }
      if (audio.paused) {
        if (audio.getAttribute("data-auto-choice") === "true") {
          autoPlayChainActive = true;
        }
        if (audio.readyState >= 4) {
          setBufferingState(false);
          audio.play().catch(() => {});
        } else {
          setBufferingState(true);
          audio.addEventListener(
            "canplaythrough",
            () => {
              setBufferingState(false);
              audio.play().catch(() => {});
            },
            { once: true }
          );
          audio.load();
        }
      } else {
        autoPlayChainActive = false;
        audio.pause();
      }
    });
  }

  audio.addEventListener("play", () => setPlayButtonVisual(true));
  audio.addEventListener("pause", () => {
    setPlayButtonVisual(false);
    if (!audio.ended && audio.currentTime > 0) {
      sendServerAction("SaveAudioTime", { time: Math.floor(audio.currentTime * 10) / 10 });
    }
  });
  audio.addEventListener("loadedmetadata", () => {
    const tot = qs("#audio-time-total");
    if (tot) tot.textContent = formatSeconds(audio.duration);
    if (slider && audio.duration > 0) {
      const val = Math.round((audio.currentTime / audio.duration) * 1000);
      slider.value = String(val);
      slider.style.setProperty("--seek-pct", (val / 10).toFixed(1) + "%");
    }
  });

  audio.addEventListener("timeupdate", () => {
    const cur = qs("#audio-time-current");
    if (cur) cur.textContent = formatSeconds(audio.currentTime);
    if (slider && audio.duration > 0) {
      const val = Math.round((audio.currentTime / audio.duration) * 1000);
      slider.value = String(val);
      slider.style.setProperty("--seek-pct", (val / 10).toFixed(1) + "%");
    }
    const now = Date.now();
    if (now - lastAudioSaveAt > 2000) {
      lastAudioSaveAt = now;
      sendServerAction("SaveAudioTime", { time: Math.floor(audio.currentTime * 10) / 10 });
    }
  });

  audio.addEventListener("ended", () => {
    setPlayButtonVisual(false);
    if (slider) {
      slider.value = "1000";
      slider.style.setProperty("--seek-pct", "100%");
    }
    sendServerAction("SaveAudioTime", { time: 0 });
    if (audio.getAttribute("data-auto-choice") === "true") {
      sendServerAction("AudioEnded", {});
    }
  });

  if (slider) {
    slider.addEventListener("input", () => {
      const val = parseFloat(slider.value) || 0;
      slider.style.setProperty("--seek-pct", (val / 10).toFixed(1) + "%");
      if (audio.duration > 0) {
        audio.currentTime = (val / 1000) * audio.duration;
      }
    });
    slider.addEventListener("change", () => {
      if (audio.duration > 0) {
        sendServerAction("SaveAudioTime", { time: Math.floor(audio.currentTime * 10) / 10 });
      }
    });
  }
}

"use strict";

let manualFocusCard = null;
let playerResizeObserver = null;

const playerScrollState = {
  cardKey: "present",
  offsetRatio: 0,
  lastWidth: 0,
  lastHeight: 0,
  lastWinW: 0,
  lastWinH: 0,
  lastSetScrollTop: null
};

function getSceneCardKey(card) {
  if (!card) return "present";
  if (card.getAttribute("data-present-scene") === "true") {
    return "present";
  }
  const hIdx = card.getAttribute("data-history-idx");
  if (hIdx !== null && hIdx !== "") {
    return "history:" + hIdx;
  }
  return "present";
}

function findSceneCardByKey(feed, cardKey) {
  if (!feed) return null;
  if (cardKey && cardKey.indexOf("history:") === 0) {
    const idx = cardKey.slice("history:".length);
    const found = qs('.scene-card[data-history-idx="' + idx + '"]', feed);
    if (found) return found;
  }
  return qs('.scene-card[data-present-scene="true"]', feed) || qs(".scene-card", feed);
}

function getSceneCardStartScrollTop(feed, card) {
  if (!feed || !card) return 0;
  const globalMeta = qs("#reader-global-meta", feed);
  const metaH = globalMeta ? globalMeta.offsetHeight : 0;
  let layoutTop = 0;
  let el = card;
  while (el && el !== feed && feed.contains(el)) {
    layoutTop += el.offsetTop;
    el = el.offsetParent;
  }
  const rawTop = layoutTop - Math.max(0, metaH - 1);
  return Math.max(0, Math.round(rawTop));
}

function recordPlayerViewportDimensions(feed) {
  if (!feed) return;
  playerScrollState.lastWidth = feed.clientWidth;
  playerScrollState.lastHeight = feed.clientHeight;
  playerScrollState.lastWinW = window.innerWidth;
  playerScrollState.lastWinH = window.innerHeight;
}

function hasPlayerViewportResized(feed) {
  if (!feed || playerScrollState.lastWidth <= 0 || playerScrollState.lastHeight <= 0) {
    return false;
  }
  return (
    feed.clientWidth !== playerScrollState.lastWidth ||
    feed.clientHeight !== playerScrollState.lastHeight ||
    window.innerWidth !== playerScrollState.lastWinW ||
    window.innerHeight !== playerScrollState.lastWinH
  );
}

function capturePlayerScrollState(feed) {
  if (!feed) return;
  const focusedCard =
    (manualFocusCard && feed.contains(manualFocusCard) ? manualFocusCard : null) ||
    qs(".scene-card.scene-focused", feed) ||
    qs('.scene-card[data-present-scene="true"]', feed) ||
    qs(".scene-card", feed);
  if (!focusedCard) return;

  playerScrollState.cardKey = getSceneCardKey(focusedCard);
  if (manualFocusCard && focusedCard === manualFocusCard) {
    playerScrollState.offsetRatio = 0;
  } else {
    const startTop = getSceneCardStartScrollTop(feed, focusedCard);
    const offsetPx = feed.scrollTop - startTop;
    if (Math.abs(offsetPx) <= 2) {
      playerScrollState.offsetRatio = 0;
    } else {
      const cardH = Math.max(1, focusedCard.offsetHeight);
      playerScrollState.offsetRatio = offsetPx / cardH;
    }
  }
  recordPlayerViewportDimensions(feed);
}

function restorePlayerScrollPosition(feed) {
  if (!feed) {
    feed = qs("#story-scroll-feed");
  }
  if (!feed) return;

  const targetCard = findSceneCardByKey(feed, playerScrollState.cardKey);
  if (!targetCard) return;

  if (manualFocusCard && feed.contains(manualFocusCard)) {
    manualFocusCard = null;
  }

  const startTop = getSceneCardStartScrollTop(feed, targetCard);
  const cardH = Math.max(1, targetCard.offsetHeight);
  const sampleHeader = qs(".scene-header-block", targetCard) || qs(".scene-header-block", feed);
  const headerH = sampleHeader ? sampleHeader.offsetHeight : 44;

  let offsetPx = Math.round(playerScrollState.offsetRatio * cardH);
  if (offsetPx > 0) {
    offsetPx = Math.min(offsetPx, Math.max(0, cardH - headerH - 2));
  } else if (offsetPx < 0) {
    offsetPx = Math.max(offsetPx, -headerH);
  }

  const targetScrollTop = Math.max(0, startTop + offsetPx);
  playerScrollState.lastSetScrollTop = targetScrollTop;
  feed.scrollTop = targetScrollTop;
  recordPlayerViewportDimensions(feed);

  updateFocusedSceneByViewport();
}

let activeScrollAnimFrame = null;

function cancelActiveScrollAnim() {
  if (activeScrollAnimFrame !== null) {
    cancelAnimationFrame(activeScrollAnimFrame);
    activeScrollAnimFrame = null;
  }
}

function animateFeedScrollTo(feed, targetOrCard, durationMs) {
  if (!feed) return;
  cancelActiveScrollAnim();
  const targetCard =
    targetOrCard && typeof targetOrCard === "object" ? targetOrCard : null;
  const resolveTarget = () => {
    const raw = targetCard
      ? getSceneCardStartScrollTop(feed, targetCard)
      : Number(targetOrCard) || 0;
    const maxScroll = Math.max(0, feed.scrollHeight - feed.clientHeight);
    return Math.min(Math.max(0, raw), maxScroll);
  };
  const startScrollTop = feed.scrollTop;
  const initialTarget = resolveTarget();
  if (Math.abs(initialTarget - startScrollTop) < 2 || durationMs <= 0) {
    playerScrollState.lastSetScrollTop = initialTarget;
    feed.scrollTop = initialTarget;
    updateFocusedSceneByViewport();
    return;
  }
  const startTime = performance.now();
  const step = (now) => {
    const elapsed = now - startTime;
    const t = Math.min(1, elapsed / durationMs);
    const eased = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
    const currentTarget = resolveTarget();
    const delta = currentTarget - startScrollTop;
    const nextScrollTop = Math.round(startScrollTop + delta * eased);
    playerScrollState.lastSetScrollTop = nextScrollTop;
    feed.scrollTop = nextScrollTop;
    updateFocusedSceneByViewport();
    if (t < 1) {
      activeScrollAnimFrame = requestAnimationFrame(step);
    } else {
      const finalTarget = resolveTarget();
      playerScrollState.lastSetScrollTop = finalTarget;
      feed.scrollTop = finalTarget;
      activeScrollAnimFrame = null;
      if (targetCard) {
        playerScrollState.cardKey = getSceneCardKey(targetCard);
        playerScrollState.offsetRatio = 0;
        recordPlayerViewportDimensions(feed);
      } else {
        capturePlayerScrollState(feed);
      }
      updateFocusedSceneByViewport();
    }
  };
  activeScrollAnimFrame = requestAnimationFrame(step);
}

function scrollSceneCardToStart(feed, card, durationMs) {
  if (!feed || !card) return;
  animateFeedScrollTo(feed, card, durationMs || 1400);
}

let isAutoAdvancingImplicit = false;
let implicitOverscrollAccum = 0;
let implicitBottomReachedAt = 0;
let implicitTouchStartY = null;
let implicitSpringResetTimer = null;
const IMPLICIT_OVERSCROLL_THRESHOLD = 150;
const IMPLICIT_MAX_PULL_PX = 100;

function applyOverscrollSpringPull(feed, accum, activePull) {
  if (!feed) return;
  const clamped = Math.max(0, Math.min(IMPLICIT_OVERSCROLL_THRESHOLD, accum));
  const ratio = clamped / IMPLICIT_OVERSCROLL_THRESHOLD;
  const pullPx = Math.round(IMPLICIT_MAX_PULL_PX * (1 - Math.pow(1 - ratio, 1.45)));
  feed.classList.toggle("is-overscrolling", Boolean(activePull && pullPx > 0));
  const transformVal = pullPx > 0 ? "translateY(-" + pullPx + "px)" : "";
  const histStack = qs("#history-stack", feed);
  const activeStage = qs("#active-scene-stage", feed);
  if (histStack) histStack.style.transform = transformVal;
  if (activeStage) activeStage.style.transform = transformVal;
}

function resetOverscrollSpringPull(feed) {
  if (implicitSpringResetTimer) {
    clearTimeout(implicitSpringResetTimer);
    implicitSpringResetTimer = null;
  }
  implicitOverscrollAccum = 0;
  if (!feed) {
    feed = qs("#story-scroll-feed");
  }
  applyOverscrollSpringPull(feed, 0, false);
}

function scheduleOverscrollSpringBack(feed) {
  if (implicitSpringResetTimer) {
    clearTimeout(implicitSpringResetTimer);
  }
  implicitSpringResetTimer = setTimeout(() => {
    implicitSpringResetTimer = null;
    if (!isAutoAdvancingImplicit) {
      resetOverscrollSpringPull(feed);
    }
  }, 150);
}

function triggerImplicitNextAdvance() {
  if (isAutoAdvancingImplicit) return;
  if (qs("#modal-confirm")) return;
  const feed = qs("#story-scroll-feed");
  if (!feed) return;
  const implicitBtn = qs('#active-scene-stage button.choice-btn[data-implicit-next="true"]', feed);
  if (!implicitBtn) return;

  if (implicitSpringResetTimer) {
    clearTimeout(implicitSpringResetTimer);
    implicitSpringResetTimer = null;
  }
  isAutoAdvancingImplicit = true;
  implicitOverscrollAccum = 0;
  sendServerAction("AutoAdvanceImplicit", {}).finally(() => {
    setTimeout(() => {
      isAutoAdvancingImplicit = false;
      implicitOverscrollAccum = 0;
      implicitBottomReachedAt = 0;
    }, 520);
  });
}

function getSceneCardFeedTop(feed, card) {
  let layoutTop = 0;
  let el = card;
  while (el && el !== feed && feed.contains(el)) {
    layoutTop += el.offsetTop;
    el = el.offsetParent;
  }
  return layoutTop;
}

function updateFeedScrollCue(feed) {
  if (!feed) return 0;
  const remaining = feed.scrollHeight - feed.scrollTop - feed.clientHeight;
  const scrollCue = qs(".scroll-more-cue", feed);
  if (scrollCue) {
    scrollCue.classList.toggle("hidden", !(remaining > 12));
  }
  return remaining;
}

let modalFeedResizeObserver = null;

function autoResizeSceneTextarea(ta) {
  if (!ta) return;
  const feed = ta.closest(".story-scroll-feed");
  const prevScrollTop = feed ? feed.scrollTop : 0;
  ta.style.minHeight = "0px";
  ta.style.height = "0px";
  const borderExtra = Math.max(2, (ta.offsetHeight - ta.clientHeight) || 0);
  const fullH = Math.max(320, ta.scrollHeight + borderExtra + 12);
  ta.style.height = fullH + "px";
  ta.style.minHeight = fullH + "px";
  ta.scrollTop = 0;
  if (feed) {
    feed.scrollTop = prevScrollTop;
    updateFeedScrollCue(feed);
  }
}

function initSceneTextModalFeed(resetScroll) {
  const feed = qs(".scene-text-editor-feed");
  if (!feed) {
    if (modalFeedResizeObserver) {
      modalFeedResizeObserver.disconnect();
      modalFeedResizeObserver = null;
    }
    return;
  }
  const ta = qs("#modal-scene-textarea", feed);
  if (ta) {
    autoResizeSceneTextarea(ta);
    if (!ta.__stBoundInput) {
      ta.__stBoundInput = true;
      ta.addEventListener("input", () => {
        autoResizeSceneTextarea(ta);
      });
      ta.addEventListener("scroll", () => {
        if (ta.scrollTop !== 0) {
          autoResizeSceneTextarea(ta);
        }
      });
    }
  }
  if (resetScroll) {
    feed.scrollTop = 0;
  }
  updateFeedScrollCue(feed);
  if (!feed.__stBoundScroll) {
    feed.__stBoundScroll = true;
    feed.addEventListener(
      "scroll",
      () => {
        updateFeedScrollCue(feed);
      },
      { passive: true }
    );
  }
  if (typeof ResizeObserver !== "undefined") {
    if (modalFeedResizeObserver) {
      modalFeedResizeObserver.disconnect();
    }
    modalFeedResizeObserver = new ResizeObserver(() => {
      const curTa = qs("#modal-scene-textarea", feed);
      if (curTa) {
        autoResizeSceneTextarea(curTa);
      } else {
        updateFeedScrollCue(feed);
      }
    });
    modalFeedResizeObserver.observe(feed);
  }
  requestAnimationFrame(() => {
    if (ta) {
      autoResizeSceneTextarea(ta);
    }
    updateFeedScrollCue(feed);
  });
}

function updateFocusedSceneByViewport() {
  const feed = qs("#story-scroll-feed");
  if (!feed) return;
  const remaining = updateFeedScrollCue(feed);
  if (remaining > 8) {
    if (implicitOverscrollAccum > 0) {
      resetOverscrollSpringPull(feed);
    }
    implicitBottomReachedAt = 0;
  } else if (implicitBottomReachedAt === 0) {
    implicitBottomReachedAt = Date.now();
  }
  const cards = qsa(".scene-card", feed);
  if (cards.length === 0) return;

  const globalMeta = qs("#reader-global-meta", feed);
  const metaH = globalMeta ? globalMeta.offsetHeight : 0;
  const sampleHeader = qs(".scene-header-block", feed);
  const headerH = sampleHeader ? sampleHeader.offsetHeight : 44;
  const focalScrollY = feed.scrollTop + metaH + headerH;

  let bestCard = null;
  let bestIdx = -1;

  if (manualFocusCard && feed.contains(manualFocusCard)) {
    const targetStart = getSceneCardStartScrollTop(feed, manualFocusCard);
    const maxScroll = Math.max(0, feed.scrollHeight - feed.clientHeight);
    const clampedTarget = Math.min(targetStart, maxScroll);
    bestCard = manualFocusCard;
    bestIdx = cards.indexOf(bestCard);
    if (Math.abs(feed.scrollTop - clampedTarget) <= 3) {
      manualFocusCard = null;
    }
  }

  if (!bestCard) {
    let lo = 0;
    let hi = cards.length - 1;
    let candidateIdx = 0;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      const top = getSceneCardFeedTop(feed, cards[mid]);
      if (top <= focalScrollY) {
        candidateIdx = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    const candCard = cards[candidateIdx];
    const candTop = getSceneCardFeedTop(feed, candCard);
    const candBottom = candTop + candCard.offsetHeight;
    if (focalScrollY > candBottom && candidateIdx + 1 < cards.length) {
      const nextCard = cards[candidateIdx + 1];
      const nextTop = getSceneCardFeedTop(feed, nextCard);
      if (Math.abs(nextTop - focalScrollY) < Math.abs(candBottom - focalScrollY)) {
        candidateIdx = candidateIdx + 1;
      }
    }
    bestIdx = candidateIdx;
    bestCard = cards[bestIdx];
  }

  for (let i = 0; i < cards.length; i++) {
    const card = cards[i];
    const isFocused = i === bestIdx;
    if (card.classList.contains("scene-focused") !== isFocused) {
      card.classList.toggle("scene-focused", isFocused);
    }
    if (card.classList.contains("scene-dimmed") !== !isFocused) {
      card.classList.toggle("scene-dimmed", !isFocused);
    }
  }

  const rail = qs("#story-history-rail");
  const railTicks = qsa("#story-history-rail .history-rail-tick");
  if (railTicks.length === cards.length) {
    const activeIdx = bestIdx;
    for (let idx = 0; idx < railTicks.length; idx++) {
      const isAct = idx === activeIdx;
      if (railTicks[idx].classList.contains("active") !== isAct) {
        railTicks[idx].classList.toggle("active", isAct);
      }
    }
    const activeTick = activeIdx >= 0 ? railTicks[activeIdx] : null;
    if (rail && activeTick && rail.scrollHeight > rail.clientHeight) {
      const tickTop = activeTick.offsetTop;
      const tickBottom = tickTop + activeTick.offsetHeight;
      if (tickTop < rail.scrollTop + 16) {
        rail.scrollTop = Math.max(0, tickTop - 16);
      } else if (tickBottom > rail.scrollTop + rail.clientHeight - 16) {
        rail.scrollTop = Math.max(0, tickBottom - rail.clientHeight + 16);
      }
    }
  }

  if (bestCard) {
    const metaEl = qs("#reader-global-meta-text");
    const metaText = bestCard.getAttribute("data-scene-meta") || "";
    if (metaEl && metaText) {
      metaEl.textContent = metaText;
    }
  }

  const bgStage = qs("#player-bg-stage");
  if (bgStage && bestCard && document.body.getAttribute("data-imageless") !== "true") {
    const imgUrl = bestCard.getAttribute("data-scene-image") || "";
    const bgImg = qs("#player-bg-img", bgStage);
    if (bgImg) {
      if (imgUrl) {
        if (bgImg.getAttribute("src") !== imgUrl) {
          bgImg.setAttribute("src", imgUrl);
        }
        bgImg.classList.remove("hidden");
      } else {
        bgImg.classList.add("hidden");
      }
    }
  }
}

function initPlayerScrollAndAudio(savedScrollTop, shouldAutoPlay, preserveTime, animateFromScrollTop) {
  initAudioController(Boolean(shouldAutoPlay), preserveTime);
  if (typeof initNodeEditorCanvas === "function") {
    initNodeEditorCanvas();
  }
  initSceneTextModalFeed(false);

  const feed = qs("#story-scroll-feed");
  if (!feed) return;

  implicitOverscrollAccum = 0;
  implicitBottomReachedAt = 0;
  implicitTouchStartY = null;

  if (animateFromScrollTop !== null && animateFromScrollTop !== undefined) {
    manualFocusCard = null;
    playerScrollState.cardKey = "present";
    playerScrollState.offsetRatio = 0;
    const presentCard =
      qs('#active-scene-stage .scene-card[data-present-scene="true"]', feed) ||
      qs("#active-scene-stage .scene-card", feed);
    if (presentCard) {
      presentCard.classList.add("scene-entering");
    }
    feed.scrollTop = animateFromScrollTop;
    recordPlayerViewportDimensions(feed);
    updateFocusedSceneByViewport();
    requestAnimationFrame(() => {
      if (presentCard) {
        scrollSceneCardToStart(feed, presentCard, 1500);
      } else {
        restorePlayerScrollPosition(feed);
      }
    });
  } else if (savedScrollTop !== null && savedScrollTop !== undefined) {
    if (!hasPlayerViewportResized(feed) && playerScrollState.lastWidth > 0) {
      playerScrollState.lastSetScrollTop = savedScrollTop;
      feed.scrollTop = savedScrollTop;
      updateFocusedSceneByViewport();
      capturePlayerScrollState(feed);
    } else {
      restorePlayerScrollPosition(feed);
    }
    requestAnimationFrame(() => {
      if (hasPlayerViewportResized(feed)) {
        restorePlayerScrollPosition(feed);
      } else {
        updateFocusedSceneByViewport();
      }
    });
  } else {
    manualFocusCard = null;
    playerScrollState.cardKey = "present";
    playerScrollState.offsetRatio = 0;
    restorePlayerScrollPosition(feed);
    requestAnimationFrame(() => {
      restorePlayerScrollPosition(feed);
    });
  }

  feed.addEventListener(
    "wheel",
    (e) => {
      cancelActiveScrollAnim();
      manualFocusCard = null;
      const implicitBtn = qs('#active-scene-stage button.choice-btn[data-implicit-next="true"]', feed);
      if (!implicitBtn || isAutoAdvancingImplicit) {
        resetOverscrollSpringPull(feed);
        return;
      }
      const remaining = feed.scrollHeight - feed.scrollTop - feed.clientHeight;
      if (remaining > 6 || e.deltaY <= 0) {
        if (e.deltaY < 0 && implicitOverscrollAccum > 0) {
          resetOverscrollSpringPull(feed);
        }
        return;
      }
      if (implicitBottomReachedAt === 0) {
        implicitBottomReachedAt = Date.now();
      }
      implicitOverscrollAccum = Math.min(
        IMPLICIT_OVERSCROLL_THRESHOLD,
        implicitOverscrollAccum + Math.abs(e.deltaY)
      );
      applyOverscrollSpringPull(feed, implicitOverscrollAccum, true);
      scheduleOverscrollSpringBack(feed);
      if (implicitOverscrollAccum >= IMPLICIT_OVERSCROLL_THRESHOLD) {
        triggerImplicitNextAdvance();
      }
    },
    { passive: true }
  );

  feed.addEventListener(
    "touchstart",
    (e) => {
      cancelActiveScrollAnim();
      if (e.touches && e.touches.length === 1) {
        implicitTouchStartY = e.touches[0].clientY;
      }
    },
    { passive: true }
  );

  feed.addEventListener(
    "touchmove",
    (e) => {
      manualFocusCard = null;
      if (implicitTouchStartY === null || !e.touches || e.touches.length !== 1) return;
      const implicitBtn = qs('#active-scene-stage button.choice-btn[data-implicit-next="true"]', feed);
      if (!implicitBtn || isAutoAdvancingImplicit) return;
      const remaining = feed.scrollHeight - feed.scrollTop - feed.clientHeight;
      if (remaining > 6) {
        implicitTouchStartY = e.touches[0].clientY;
        if (implicitOverscrollAccum > 0) {
          resetOverscrollSpringPull(feed);
        }
        return;
      }
      const dragUp = implicitTouchStartY - e.touches[0].clientY;
      if (dragUp <= 0) {
        resetOverscrollSpringPull(feed);
        return;
      }
      const mappedAccum = Math.min(IMPLICIT_OVERSCROLL_THRESHOLD, (dragUp / 65) * IMPLICIT_OVERSCROLL_THRESHOLD);
      implicitOverscrollAccum = mappedAccum;
      applyOverscrollSpringPull(feed, implicitOverscrollAccum, true);
      if (dragUp >= 65) {
        implicitTouchStartY = null;
        triggerImplicitNextAdvance();
      }
    },
    { passive: true }
  );

  feed.addEventListener(
    "touchend",
    () => {
      implicitTouchStartY = null;
      if (!isAutoAdvancingImplicit && implicitOverscrollAccum > 0) {
        resetOverscrollSpringPull(feed);
      }
    },
    { passive: true }
  );

  feed.addEventListener(
    "touchcancel",
    () => {
      implicitTouchStartY = null;
      if (!isAutoAdvancingImplicit && implicitOverscrollAccum > 0) {
        resetOverscrollSpringPull(feed);
      }
    },
    { passive: true }
  );

  feed.addEventListener(
    "scroll",
    () => {
      if (hasPlayerViewportResized(feed)) {
        restorePlayerScrollPosition(feed);
        return;
      }
      if (
        playerScrollState.lastSetScrollTop !== null &&
        Math.abs(feed.scrollTop - playerScrollState.lastSetScrollTop) <= 1
      ) {
        playerScrollState.lastSetScrollTop = null;
        updateFocusedSceneByViewport();
        return;
      }
      playerScrollState.lastSetScrollTop = null;
      updateFocusedSceneByViewport();
      capturePlayerScrollState(feed);
    },
    { passive: true }
  );

  if (typeof ResizeObserver !== "undefined") {
    if (playerResizeObserver) {
      playerResizeObserver.disconnect();
    }
    playerResizeObserver = new ResizeObserver(() => {
      if (hasPlayerViewportResized(feed)) {
        restorePlayerScrollPosition(feed);
      }
    });
    playerResizeObserver.observe(feed);
  }

  qsa("#story-history-rail .history-rail-tick").forEach((tick, idx) => {
    tick.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const cards = qsa(".scene-card", feed);
      const targetCard = cards[idx];
      if (!targetCard) return;
      manualFocusCard = targetCard;
      playerScrollState.cardKey = getSceneCardKey(targetCard);
      playerScrollState.offsetRatio = 0;
      recordPlayerViewportDimensions(feed);
      updateFocusedSceneByViewport();
      scrollSceneCardToStart(feed, targetCard);
    });
  });

  qsa(".scene-card", feed).forEach((card) => {
    card.addEventListener("click", (e) => {
      if (e.target.closest("button") || e.target.closest("[action]")) {
        return;
      }
      if (card.classList.contains("scene-dimmed")) {
        manualFocusCard = card;
        playerScrollState.cardKey = getSceneCardKey(card);
        playerScrollState.offsetRatio = 0;
        recordPlayerViewportDimensions(feed);
        updateFocusedSceneByViewport();
        scrollSceneCardToStart(feed, card);
      }
    });
  });
}

"use strict";

const EDITOR_GRID_SIZE = 24;
const NODE_CARD_WIDTH = 192;
const NODE_HEADER_HEIGHT = 34;
const NODE_CHOICE_ROW_HEIGHT = 26;
const NODE_FOOTER_HEIGHT = 40;
const NODE_BASE_HEIGHT = 74;
const PORT_RADIUS = 6.5;
const CHAPTER_OUT_PORT_PITCH = 37;

// Texture 0: Dedicated 256x64 UI Sprite Atlas (solid white, SDF ports, 90° wire corners, 2x3 grip)
const UI_ATLAS_W = 256;
const UI_ATLAS_H = 64;

// Texture 1: Dedicated 512x512 Font MSDF Texture (/studio-atlas.png)
const FONT_ATLAS_SIZE = 512;
const MSDF_BASE_EM_PX = 23.0;
const MSDF_PIXEL_RANGE = 3.0;

// 3 real TrueType fonts baked into /studio-atlas.png at build time:
// 0 = Aleo-Regular.ttf, 1 = Lato-Regular.ttf, 2 = Lato-Bold.ttf
const MSDF_FONT_ALEO_REG = 0;
const MSDF_FONT_LATO_REG = 1;
